-- ============================================================================
-- File:        02-oltp-tuning/01_schema_normalized.sql
-- Purpose:     Normalized Hotel Booking OLTP Schema (3NF)
--              - Surrogate IDENTITY primary keys (NUMBER GENERATED BY DEFAULT)
--              - Exact NUMBER(12,2) monetary columns with NOT NULL & CHECK guards
--              - Explicit Foreign Key indexes (prevent parent TM locks & FTS)
--              - Composite availability & status-date indexes on ts_hotel_idx
-- Execution:   Run in FREEPDB1 connected as HOTEL_APP (or SYSDBA).
-- ============================================================================

WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
SET SERVEROUTPUT ON

ALTER SESSION SET CONTAINER = FREEPDB1;
ALTER SESSION SET CURRENT_SCHEMA = hotel_app;

-- 1. Room Types (Master Catalog)
CREATE TABLE hotel_app.room_types (
  room_type_id       NUMBER GENERATED BY DEFAULT AS IDENTITY
                     CONSTRAINT pk_room_types PRIMARY KEY
                     USING INDEX TABLESPACE ts_hotel_idx,
  type_code          VARCHAR2(30)  NOT NULL
                     CONSTRAINT uq_room_types_code UNIQUE
                     USING INDEX TABLESPACE ts_hotel_idx,
  type_name          VARCHAR2(100) NOT NULL,
  base_nightly_rate  NUMBER(12,2)  NOT NULL
                     CONSTRAINT chk_rt_rate_pos CHECK (base_nightly_rate > 0),
  max_occupancy      NUMBER(2)     NOT NULL
                     CONSTRAINT chk_rt_occ_range CHECK (max_occupancy BETWEEN 1 AND 12),
  created_at         TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL
) TABLESPACE ts_hotel_data;

-- 2. Rooms (Physical Inventory)
CREATE TABLE hotel_app.rooms (
  room_id            NUMBER GENERATED BY DEFAULT AS IDENTITY
                     CONSTRAINT pk_rooms PRIMARY KEY
                     USING INDEX TABLESPACE ts_hotel_idx,
  room_number        VARCHAR2(16)  NOT NULL
                     CONSTRAINT uq_rooms_number UNIQUE
                     USING INDEX TABLESPACE ts_hotel_idx,
  room_type_id       NUMBER        NOT NULL
                     CONSTRAINT fk_rooms_room_type REFERENCES hotel_app.room_types (room_type_id),
  floor_number       NUMBER(3)     NOT NULL
                     CONSTRAINT chk_rooms_floor CHECK (floor_number >= 0),
  status             VARCHAR2(20)  DEFAULT 'AVAILABLE' NOT NULL
                     CONSTRAINT chk_rooms_status CHECK (status IN ('AVAILABLE', 'OCCUPIED', 'MAINTENANCE', 'OUT_OF_SERVICE')),
  is_active          CHAR(1)       DEFAULT 'Y' NOT NULL
                     CONSTRAINT chk_rooms_active CHECK (is_active IN ('Y', 'N')),
  created_at         TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL
) TABLESPACE ts_hotel_data;

-- Explicit FK index on rooms(room_type_id)
CREATE INDEX hotel_app.idx_rooms_type_id
  ON hotel_app.rooms (room_type_id)
  TABLESPACE ts_hotel_idx;

-- 3. Customers
CREATE TABLE hotel_app.customers (
  customer_id        NUMBER GENERATED BY DEFAULT AS IDENTITY
                     CONSTRAINT pk_customers PRIMARY KEY
                     USING INDEX TABLESPACE ts_hotel_idx,
  email              VARCHAR2(255) NOT NULL
                     CONSTRAINT uq_customers_email UNIQUE
                     USING INDEX TABLESPACE ts_hotel_idx,
  full_name          VARCHAR2(150) NOT NULL,
  phone_number       VARCHAR2(30),
  loyalty_tier       VARCHAR2(20)  DEFAULT 'STANDARD' NOT NULL
                     CONSTRAINT chk_cust_loyalty CHECK (loyalty_tier IN ('STANDARD', 'SILVER', 'GOLD', 'PLATINUM')),
  created_at         TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL
) TABLESPACE ts_hotel_data;

-- 4. Bookings (Reservation Header)
CREATE TABLE hotel_app.bookings (
  booking_id         NUMBER GENERATED BY DEFAULT AS IDENTITY
                     CONSTRAINT pk_bookings PRIMARY KEY
                     USING INDEX TABLESPACE ts_hotel_idx,
  booking_ref        VARCHAR2(32)  NOT NULL
                     CONSTRAINT uq_bookings_ref UNIQUE
                     USING INDEX TABLESPACE ts_hotel_idx,
  customer_id        NUMBER        NOT NULL
                     CONSTRAINT fk_bookings_customer REFERENCES hotel_app.customers (customer_id),
  check_in_date      DATE          NOT NULL,
  check_out_date     DATE          NOT NULL,
  booking_status     VARCHAR2(20)  DEFAULT 'CONFIRMED' NOT NULL
                     CONSTRAINT chk_bookings_status CHECK (booking_status IN ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')),
  created_at         TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at         TIMESTAMP WITH TIME ZONE,
  CONSTRAINT chk_bookings_date_range CHECK (check_out_date > check_in_date)
) TABLESPACE ts_hotel_data;

-- Explicit FK index on bookings(customer_id) + check_in_date for history sorting
CREATE INDEX hotel_app.idx_bookings_customer_id
  ON hotel_app.bookings (customer_id, check_in_date DESC)
  TABLESPACE ts_hotel_idx;

-- Composite operational index for front-desk arrivals / departures dashboards
CREATE INDEX hotel_app.idx_bookings_status_dates
  ON hotel_app.bookings (booking_status, check_in_date, check_out_date)
  TABLESPACE ts_hotel_idx;

-- 5. Booking Rooms (Reservation Line Items / Availability Enforcement)
CREATE TABLE hotel_app.booking_rooms (
  booking_room_id      NUMBER GENERATED BY DEFAULT AS IDENTITY
                       CONSTRAINT pk_booking_rooms PRIMARY KEY
                       USING INDEX TABLESPACE ts_hotel_idx,
  booking_id           NUMBER       NOT NULL
                       CONSTRAINT fk_br_booking REFERENCES hotel_app.bookings (booking_id),
  room_id              NUMBER       NOT NULL
                       CONSTRAINT fk_br_room REFERENCES hotel_app.rooms (room_id),
  check_in_date        DATE         NOT NULL,
  check_out_date       DATE         NOT NULL,
  agreed_nightly_rate  NUMBER(12,2) NOT NULL
                       CONSTRAINT chk_br_rate_pos CHECK (agreed_nightly_rate > 0),
  CONSTRAINT uq_booking_rooms_pair UNIQUE (booking_id, room_id)
    USING INDEX TABLESPACE ts_hotel_idx,
  CONSTRAINT chk_br_date_range CHECK (check_out_date > check_in_date)
) TABLESPACE ts_hotel_data;

-- Note: booking_id FK is indexed as the leading column of uq_booking_rooms_pair(booking_id, room_id).
-- Covering composite availability index covers BOTH room_id FK AND date-range overlap probes
-- (including booking_id eliminates TABLE ACCESS BY INDEX ROWID on booking_rooms during joins):
CREATE INDEX hotel_app.idx_br_room_dates
  ON hotel_app.booking_rooms (room_id, check_in_date, check_out_date, booking_id)
  TABLESPACE ts_hotel_idx;

-- 6. Services (Ancillary Add-On Catalog)
CREATE TABLE hotel_app.services (
  service_id         NUMBER GENERATED BY DEFAULT AS IDENTITY
                     CONSTRAINT pk_services PRIMARY KEY
                     USING INDEX TABLESPACE ts_hotel_idx,
  service_code       VARCHAR2(30)  NOT NULL
                     CONSTRAINT uq_services_code UNIQUE
                     USING INDEX TABLESPACE ts_hotel_idx,
  service_name       VARCHAR2(120) NOT NULL,
  unit_price         NUMBER(12,2)  NOT NULL
                     CONSTRAINT chk_svc_price_nn CHECK (unit_price >= 0),
  is_active          CHAR(1)       DEFAULT 'Y' NOT NULL
                     CONSTRAINT chk_svc_active CHECK (is_active IN ('Y', 'N'))
) TABLESPACE ts_hotel_data;

-- 7. Service Orders (Ancillary Consumption Linked to a Booking)
CREATE TABLE hotel_app.service_orders (
  service_order_id     NUMBER GENERATED BY DEFAULT AS IDENTITY
                       CONSTRAINT pk_service_orders PRIMARY KEY
                       USING INDEX TABLESPACE ts_hotel_idx,
  booking_id           NUMBER       NOT NULL
                       CONSTRAINT fk_so_booking REFERENCES hotel_app.bookings (booking_id),
  service_id           NUMBER       NOT NULL
                       CONSTRAINT fk_so_service REFERENCES hotel_app.services (service_id),
  quantity             NUMBER(6)    NOT NULL
                       CONSTRAINT chk_so_qty_pos CHECK (quantity > 0),
  unit_price_snapshot  NUMBER(12,2) NOT NULL
                       CONSTRAINT chk_so_price_nn CHECK (unit_price_snapshot >= 0),
  ordered_at           TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL
) TABLESPACE ts_hotel_data;

-- Explicit FK indexes on service_orders
CREATE INDEX hotel_app.idx_so_booking_id
  ON hotel_app.service_orders (booking_id, service_id)
  TABLESPACE ts_hotel_idx;

CREATE INDEX hotel_app.idx_so_service_id
  ON hotel_app.service_orders (service_id)
  TABLESPACE ts_hotel_idx;

-- 8. Invoices (1-to-1 Financial Folio per Booking)
CREATE TABLE hotel_app.invoices (
  invoice_id         NUMBER GENERATED BY DEFAULT AS IDENTITY
                     CONSTRAINT pk_invoices PRIMARY KEY
                     USING INDEX TABLESPACE ts_hotel_idx,
  booking_id         NUMBER       NOT NULL
                     CONSTRAINT uq_invoices_booking UNIQUE
                     USING INDEX TABLESPACE ts_hotel_idx
                     CONSTRAINT fk_invoices_booking REFERENCES hotel_app.bookings (booking_id),
  room_subtotal      NUMBER(12,2) DEFAULT 0 NOT NULL
                     CONSTRAINT chk_inv_room_nn CHECK (room_subtotal >= 0),
  service_subtotal   NUMBER(12,2) DEFAULT 0 NOT NULL
                     CONSTRAINT chk_inv_svc_nn CHECK (service_subtotal >= 0),
  tax_amount         NUMBER(12,2) DEFAULT 0 NOT NULL
                     CONSTRAINT chk_inv_tax_nn CHECK (tax_amount >= 0),
  total_amount       NUMBER(12,2) DEFAULT 0 NOT NULL
                     CONSTRAINT chk_inv_total_nn CHECK (total_amount >= 0),
  invoice_status     VARCHAR2(20) DEFAULT 'DRAFT' NOT NULL
                     CONSTRAINT chk_inv_status CHECK (invoice_status IN ('DRAFT', 'ISSUED', 'PAID', 'VOID')),
  issued_at          TIMESTAMP WITH TIME ZONE,
  CONSTRAINT chk_inv_total_math CHECK (total_amount = room_subtotal + service_subtotal + tax_amount)
) TABLESPACE ts_hotel_data;

-- 9. Automated Unindexed Foreign Key Verification Query (Expect 0 Rows)
PROMPT === Unindexed Foreign Key Check (Must Return 0 Rows) ===
SELECT c.table_name,
       c.constraint_name,
       cc.column_name
  FROM all_constraints c
  JOIN all_cons_columns cc
    ON cc.owner           = c.owner
   AND cc.constraint_name = c.constraint_name
 WHERE c.owner            = 'HOTEL_APP'
   AND c.constraint_type  = 'R'
   AND NOT EXISTS (
         SELECT 1
           FROM all_ind_columns ic
           JOIN all_indexes i
             ON i.owner      = ic.index_owner
            AND i.index_name = ic.index_name
          WHERE ic.table_owner     = c.owner
            AND ic.table_name      = c.table_name
            AND ic.column_name     = cc.column_name
            AND ic.column_position = cc.position
            AND i.status           = 'VALID'
            AND i.visibility       = 'VISIBLE'
       );
